SHEETS={'gpi':'chatjip','gem':'gemhwang'}
JOBS=[]

def board(key, paths):
    dest=WAVE/'references'/f'{key}.png';dest.parent.mkdir(parents=True,exist_ok=True)
    canvas=Image.new('RGB',(1800,((len(paths)+2)//3)*650),'#243047');d=ImageDraw.Draw(canvas)
    for i,p in enumerate(paths):
        p=Path(p);im=Image.open(p).convert('RGBA');im.thumbnail((590,610),Image.Resampling.LANCZOS);x=i%3*600;y=i//3*650
        canvas.paste(im,(x+(600-im.width)//2,y+35),im);d.text((x+8,y+5),f'{i+1}: {p.name}',font=font(17),fill='white')
    canvas.save(dest)
    return dest.relative_to(ROOT).as_posix()

def character(key):
    folder=ART/('portrait' if key in ['pico','dots','jepa'] else 'bust')
    paths=[folder/f'{key}.webp',folder/f'{key}-moods.webp']
    if key in ['pico','jepa']:
        paths+=[ROOT.parent/f'story/gpt-image/final-entities-v01/characters/{key}/master-v01.png']
    elif key not in ['dots','lecun']:
        parent=ROOT.parent/f'story/gpt-image/enemy-sheets-v01/characters/{SHEETS.get(key,key)}'
        paths+=(sorted(parent.glob('master-illustration*.png')) or sorted(parent.glob('master-v*.png')))[:1]
    return board('char-'+key,paths)

def add(key,kind,scene,actors=(),mechs=(),refs=(),**extra):
    references=[character(a)for a in actors]
    if mechs:references.append(board('mechs-'+key,[ART/'mech'/f'{m}.webp'for m in mechs]))
    references+=list(refs)
    if kind=='cg':references+=['public/v2/art/cg-gpi-entrance.webp']
    elif kind=='bg':references+=['public/v2/art/bg/talk-dorm.webp','public/v2/art/bg/talk-tea-room.webp']
    prompt='Use case: '+('identity-preserve' if kind=='bust' else 'illustration-story')+'. '+STYLE+RULES+(CG if kind=='cg' else BG if kind=='bg' else '')+scene
    prompt+=' Reference boards are identity/design guides only; NEVER copy their labels, montage layout, logos or sheet borders.'
    assert len(references)<=5,(key,references)
    p=WAVE/'prompts'/f'{key}-a1.txt';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(prompt+'\n',encoding='utf8')
    JOBS.append(dict(key=key,kind=kind,prompt=prompt,promptFile=p.relative_to(WAVE).as_posix(),references=references,transparent=kind in ['portrait','mech','bust'],**extra))

